-- Migração: várias coleções (Fase 1 — só banco, aditiva). Rode depois de todas as anteriores. Idempotente.
--
-- Ideia central: o código de cada item continua único na plataforma inteira. O Álbum Copa mantém
-- os códigos de hoje (BRA1, FWC3, LIL1…) e a Adrenalyn XL usa AXL1–AXL630. Por isso collection,
-- sticker_prices, pedidos e carrinhos seguem funcionando sem trocar chaves.
--
-- Nada é apagado nem renomeado: o app em produção continua lendo o que lê hoje.
--   • albums: ganha slug, nome do item (figurinha/card) e total. Entra a "Adrenalyn XL" INATIVA
--     (não aparece no cadastro até a Fase 2).
--   • stickers: aceita os tipos de bloco da Adrenalyn e ganha número, nome, seleção, tipo de card e
--     posição. Recebe os 630 cards (fonte: data/adrenalyn-xl.csv).
--   • user_albums (nova): coleções que cada pessoa acompanha, com nome próprio. Todos os usuários
--     atuais entram no Álbum Copa com o nome que já usam; contas novas entram por trigger.
--   • shop_albums (nova): configuração da loja por coleção (ativa, pedido mínimo, preços por grupo).
--     Copiada de shops para o Álbum Copa. Até a Fase 3 o app ainda usa as colunas de shops — a
--     migração da Fase 3 recopia os valores antes de trocar.
--   • orders, cart_holds, collection_shares: ganham album_id (padrão: Álbum Copa).

-- ---------- albums ----------
alter table public.albums add column if not exists slug          text;
alter table public.albums add column if not exists item_singular text not null default 'figurinha';
alter table public.albums add column if not exists item_plural   text not null default 'figurinhas';
alter table public.albums add column if not exists total_items   int;

update public.albums
   set name = 'Álbum Copa do Mundo 2026', slug = 'copa-2026', total_items = 994
 where id = 'wc2026-panini';

values ('wc2026-adrenalyn', 'Adrenalyn XL', 'adrenalyn-xl', 'card', 'cards', 630, false, 2)
on conflict (id) do update
  set name = excluded.name, slug = excluded.slug, item_singular = excluded.item_singular,
      item_plural = excluded.item_plural, total_items = excluded.total_items;

create unique index if not exists albums_slug_key on public.albums(slug);

-- ---------- stickers ----------
alter table public.stickers drop constraint if exists stickers_block_type_check;
alter table public.stickers
  add constraint stickers_block_type_check
  check (block_type in ('TEAM','FWC','CC','LEG','SPECIAL','CONTENDER'));

alter table public.stickers add column if not exists number          int;
alter table public.stickers add column if not exists name            text;
alter table public.stickers add column if not exists team_code       text;
alter table public.stickers add column if not exists card_type       text;
alter table public.stickers add column if not exists player_position text;

alter table public.stickers drop constraint if exists stickers_player_position_check;
alter table public.stickers
  add constraint stickers_player_position_check
  check (player_position is null or player_position in ('GK','DEF','MID','FWD'));

create index if not exists stickers_album_idx on public.stickers(album_id, position);

on conflict (code) do update
  set album_id = excluded.album_id, block_id = excluded.block_id, block_name = excluded.block_name,
      block_type = excluded.block_type, group_key = excluded.group_key, position = excluded.position,
      number = excluded.number, name = excluded.name, team_code = excluded.team_code,
      card_type = excluded.card_type, player_position = excluded.player_position;

-- ---------- user_albums ----------
create table if not exists public.user_albums (
  user_id         uuid not null references auth.users(id) on delete cascade,
  album_id        text not null references public.albums(id),
  collection_name text,
  position        int  not null default 0,
  created_at      timestamptz not null default now(),
  primary key (user_id, album_id)
);

alter table public.user_albums enable row level security;

drop policy if exists "users manage their own albums" on public.user_albums;
create policy "users manage their own albums"
  on public.user_albums for all to authenticated
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Usuários atuais: todos colecionam o Álbum Copa (é o único que existe até aqui).
select u.id, 'wc2026-panini', nullif(btrim(u.raw_user_meta_data->>'collection_name'), '')
  from auth.users u
on conflict (user_id, album_id) do nothing;

-- Contas novas: entram na coleção escolhida no cadastro (user_metadata.album_id), se ela existir
-- e estiver ativa; senão, no Álbum Copa.
create or replace function public.handle_new_user_album()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_album text := new.raw_user_meta_data->>'album_id';
begin
  if v_album is null or not exists (select 1 from public.albums a where a.id = v_album and a.active) then
    v_album := 'wc2026-panini';
  end if;
  values (new.id, v_album, nullif(btrim(new.raw_user_meta_data->>'collection_name'), ''))
  on conflict (user_id, album_id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created_album on auth.users;
create trigger on_auth_user_created_album
  after insert on auth.users
  for each row execute function public.handle_new_user_album();

-- ---------- shop_albums ----------
create table if not exists public.shop_albums (
  user_id         uuid not null references public.shops(user_id) on delete cascade,
  album_id        text not null references public.albums(id),
  enabled         boolean not null default true,
  min_order_cents int  not null default 0 check (min_order_cents >= 0),
  group_prices    jsonb not null default '{}'::jsonb,       -- { "TEAM": 150, "FWC": 300, … } (centavos)
  updated_at      timestamptz not null default now(),
  primary key (user_id, album_id)
);

alter table public.shop_albums enable row level security;

drop policy if exists "users manage their own shop albums" on public.shop_albums;
create policy "users manage their own shop albums"
  on public.shop_albums for all to authenticated
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

select s.user_id, 'wc2026-panini', s.min_order_cents,
       jsonb_strip_nulls(jsonb_build_object(
         'FWC', s.price_fwc_cents, 'TEAM', s.price_team_cents,
         'CC',  s.price_cc_cents,  'LEG',  s.price_leg_cents))
  from public.shops s
on conflict (user_id, album_id) do nothing;

-- ---------- pedidos, carrinhos e links públicos ----------
alter table public.orders
  add column if not exists album_id text not null default 'wc2026-panini' references public.albums(id);
alter table public.cart_holds
  add column if not exists album_id text not null default 'wc2026-panini' references public.albums(id);
alter table public.collection_shares
  add column if not exists album_id text not null default 'wc2026-panini' references public.albums(id);
